const roleSelect = document.querySelector('select[name="role"]');
roleSelect?.addEventListener('invalid', () => roleSelect.setCustomValidity('Anda blm memilih role'));
roleSelect?.addEventListener('change', () => roleSelect.setCustomValidity(''));
document.querySelector('.password-toggle')?.addEventListener('click', function () { const password = document.getElementById(this.getAttribute('aria-controls')); const show = password.type === 'password'; password.type = show ? 'text' : 'password'; this.textContent = show ? 'Sembunyikan' : 'Tampilkan'; this.setAttribute('aria-label', show ? 'Sembunyikan kata sandi' : 'Tampilkan kata sandi'); this.setAttribute('aria-pressed', String(show)); });
